    @_mutmut_mutated(mutants_xǁRiskPolicyǁ_adjust_day__mutmut)
    def _adjust_day(self, value: float, flows_cumulative: float) -> float:
        baseline = self._state.flow_baseline_day
        if baseline is None:
            baseline = 0.0
        return value - (flows_cumulative - baseline)

